\ref{ppOlk28ha12iib}: First, suppose that
$\boldsymbol{x}=(x,y^*)\in\bigcap_{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A}
\bigcap_{\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$. Then 
\begin{align} &\hskip -2mm
(\forall\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A)(\forall\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B)\quad
\pair{(a,b^*)-(x,y^*)}{(a^*,b)-(-L^*y^*,Lx)}\nonumber\\
&\hskip 60mm =\pair{(a-x,b^*-y^*)}{(a^*+L^*y^*,b-Lx)}\nonumber\\
&\hskip 60mm =\pair{a-x}{a^*+L^*y^*}+\pair{b-Lx}{b^*-y^*}\nonumber\\
&\hskip 60mm =\eta_{\mathsf{a},\mathsf{b}}-\pair{\boldsymbol{x}}
{\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}}\nonumber\\
&\hskip 60mm \ensuremath{\geqslant} 0.
\end{align}
On the other hand, since 
\begin{equation} \menge{\big((a,b^*),(a^*,b)\big)}{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A, 
\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}=\ensuremath{\text{\rm gra}\,}\boldsymbol{M}, 
\end{equation}
it follows from \eqref{egVxZ5y820} and \eqref{epOlk28ha11} that
$((x,y^*),(-L^*y^*,Lx))\in\ensuremath{\text{\rm gra}\,}\boldsymbol{M}$, i.e., 
$\boldsymbol{x}\in\boldsymbol{Z}$. Thus 
\begin{equation} \bigcap_{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A}\bigcap_{\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}\subset\boldsymbol{Z}.
\end{equation}
Conversely, let $\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A$, let $\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B$,
and let $(x,y^*)\in\boldsymbol{Z}$. 
Then $(x,-L^*y^*)\in\ensuremath{\text{\rm gra}\,} A$ and $(Lx,y^*)\in\ensuremath{\text{\rm gra}\,} B$. Since
$A$ and $B$ are monotone, we obtain
\begin{equation}
\pair{a-x}{a^*+L^*y^*}\ensuremath{\geqslant} 0
\quad\text{and}\quad
\pair{b-Lx}{b^*-y^*}\ensuremath{\geqslant} 0.
\end{equation}
Adding these two inequalities yields
\begin{equation}
\pair{x-a}{a^*+L^*y^*}+\pair{Lx-b}{b^*-y^*}\ensuremath{\leqslant} 0
\end{equation}
and, therefore,
\begin{align} \pair{\boldsymbol{x}}{\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}}
&=\pair{x}{a^*+L^*b^*}+\pair{b-La}{y^*}\nonumber\\
&=\pair{x}{a^*+L^*y^*}+\pair{Lx}{b^*-y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&=\pair{x-a}{a^*+L^*y^*}+\pair{a}{a^*}+\pair{La}{y^*}\nonumber\\
&\quad\;+\pair{Lx-b}{b^*-y^*}+\pair{b}{b^*}-\pair{b}{y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&\ensuremath{\leqslant}\pair{a}{a^*}+\pair{b}{b^*}+\pair{La-b}{y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&=\pair{a}{a^*}+\pair{b}{b^*}\nonumber\\
&=\eta_{\mathsf{a},\mathsf{b}}.
\end{align}
This implies that 
$(x,y^*)\in\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$. Hence, 
$\boldsymbol{Z}\subset\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$.

